/**
 * CT Delivery App logo — as a data URL, so it can be embedded in a
 * driver-printed customer receipt (see printReceiptForCustomer_ in app.js)
 * fully offline, with zero network round trip. Same PNG bytes as
 * CT_LOGO_PNG_BASE64_ in Code.gs, which uses it in the server-generated
 * delivery-confirmation PDF/email attachment — kept as two separate
 * copies (one per runtime) rather than one shared source, since Code.gs
 * and app.js ship and deploy completely independently of each other.
 * Loaded as a plain global (not a module) so app.js can reference
 * CT_LOGO_DATA_URL directly — include this script tag BEFORE app.js in
 * index.html, and keep it in service-worker.js's SHELL_FILES so it is
 * cached for offline use like every other shell file.
 */
const CT_LOGO_DATA_URL = "data:image/png;base64,";
